import http.server as h, functools
P = '/gemovel-integrative-project'
class H(h.SimpleHTTPRequestHandler):
    extensions_map = {'.js': 'text/javascript', '.json': 'application/json', '.css': 'text/css', '.svg': 'image/svg+xml', '.html': 'text/html', '.woff2': 'font/woff2'}
    def translate_path(s, p):
        return super().translate_path(p[len(P):] if p.startswith(P + '/') else '/__fora__')
    def end_headers(s):
        s.send_header('Cache-Control', 'no-store')
        super().end_headers()
h.ThreadingHTTPServer(('127.0.0.1', 5600), functools.partial(H, directory='site')).serve_forever()
